package br.com.admeclesial.interfaces.web.relatorio;
import br.com.admeclesial.application.relatorio.*; import br.com.admeclesial.domain.financeiro.StatusObrigacaoRepasse; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.UUID;
@Controller @RequestMapping("/relatorios/repasses-curia") public class RelatorioRepasseWebController { private final RelatorioRepasseApplicationService service; private final RelatorioContextoService contexto; public RelatorioRepasseWebController(RelatorioRepasseApplicationService s,RelatorioContextoService c){service=s;contexto=c;}
 @GetMapping public String tela(@RequestParam(required=false) UUID organizacaoUuid,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate vencimentoInicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate vencimentoFim,@RequestParam(required=false) StatusObrigacaoRepasse status,@RequestParam(required=false) Boolean somenteVencidos,@RequestParam(defaultValue="false") boolean filtroAplicado,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="25") int tamanho,Model m){m.addAttribute("organizacoes",contexto.organizacoesAutorizadas());m.addAttribute("statusOpcoes",StatusObrigacaoRepasse.values());m.addAttribute("organizacaoUuid",organizacaoUuid);m.addAttribute("vencimentoInicio",vencimentoInicio);m.addAttribute("vencimentoFim",vencimentoFim);m.addAttribute("status",status);boolean vencidosEfetivo=filtroAplicado?Boolean.TRUE.equals(somenteVencidos):true;m.addAttribute("somenteVencidos",vencidosEfetivo);if(organizacaoUuid!=null){var f=new RelatorioRepasseFiltro(organizacaoUuid,vencimentoInicio,vencimentoFim,status,vencidosEfetivo,pagina,tamanho);m.addAttribute("resultado",service.pesquisar(f));m.addAttribute("resumo",service.resumo(f));}return "relatorio/repasses-curia";}
}
